source
<?php

declare(strict_types=1);

namespace Orbit\Core\Progress;

use Symfony\Component\Console\Output\OutputInterface;
use Symfony\Component\Console\Output\StreamOutput;

final class LiveRepaintOutput
{
    public static function supports(OutputInterface $output): bool
    {
        $stream = self::resolveStream($output);

        if (is_resource($stream)) {
            if (function_exists('stream_isatty') && stream_isatty($stream)) {
                return true;
            }
        }

        return $output->isDecorated();
    }

    public static function resolveStream(OutputInterface $output): mixed
    {
        if ($output instanceof StreamOutput) {
            return $output->getStream();
        }

        if (method_exists($output, 'getOutput')) {
            $underlying = $output->getOutput();

            if ($underlying instanceof OutputInterface) {
                return self::resolveStream($underlying);
            }
        }

        return null;
    }
}

test
<?php

declare(strict_types=1);

use Orbit\Core\Progress\LiveRepaintOutput;
use Symfony\Component\Console\Output\BufferedOutput;
use Symfony\Component\Console\Output\StreamOutput;

it('supports decorated output even when the stream is not a tty', function (): void {
    $stream = fopen('php://memory', 'w+');

    expect($stream)
        ->toBeResource()
        ->and(LiveRepaintOutput::supports(new StreamOutput($stream, decorated: true)))
        ->toBeTrue();
});

it('rejects undecorated output when the stream is not a tty', function (): void {
    $stream = fopen('php://memory', 'w+');

    expect($stream)
        ->toBeResource()
        ->and(LiveRepaintOutput::supports(new StreamOutput($stream, decorated: false)))
        ->toBeFalse();
});

it('keeps live repaint support narrowed to stream tty detection and console decoration', function (): void {
    $source = file_get_contents(__DIR__.'/../../src/Progress/LiveRepaintOutput.php');

    expect($source)
        ->toContain('stream_isatty')
        ->and($source)
        ->toContain('isDecorated')
        ->and($source)
        ->not->toContain('posix_isatty');
});

it('respects injected non-stream BufferedOutput and does not fall back to global STDOUT', function (): void {
    $output = new BufferedOutput(decorated: false);

    expect(LiveRepaintOutput::resolveStream($output))
        ->toBeNull()
        ->and(LiveRepaintOutput::supports($output))
        ->toBeFalse();
});

